const __raw = $input.item.json.body || {};
const body = { ...__raw };
for (const __k in __raw) { const __v = __raw[__k]; if (__v && typeof __v === 'object' && !Array.isArray(__v)) Object.assign(body, __v); }

const customerName = (body.customer_name || 'Valued Customer').trim();
const customerPhone = (body.customer_phone || '').trim();
const dateStr = (body.date || '').trim();
const timeStr = (body.time || '10:00 AM').trim();
const service = (body.service || 'General Service / Consultation').trim();
const notes = (body.notes || '').trim();
const durationMinutes = parseInt(body.duration_minutes || '60', 10);
const timeZone = (body.timezone || $env.BUSINESS_TIMEZONE || 'America/New_York');
const businessName = ($env.BUSINESS_NAME || 'Front Office');

// Parse 12h or 24h time into 24h hour/minute
let hour = 10, minute = 0;
const m12 = timeStr.match(/(\d{1,2}):(\d{2})\s*(AM|PM)?/i);
if (m12) {
  hour = parseInt(m12[1], 10); minute = parseInt(m12[2], 10);
  const mer = (m12[3] || '').toUpperCase();
  if (mer === 'PM' && hour < 12) hour += 12;
  if (mer === 'AM' && hour === 12) hour = 0;
} else {
  const ms = timeStr.match(/(\d{1,2})\s*(AM|PM)/i);
  if (ms) { hour = parseInt(ms[1], 10); if (ms[2].toUpperCase() === 'PM' && hour < 12) hour += 12; if (ms[2].toUpperCase() === 'AM' && hour === 12) hour = 0; }
}

const pad = n => String(n).padStart(2, '0');
const [Y, Mo, D] = dateStr.split('-').map(x => parseInt(x, 10));

// DST-aware offset (e.g. "-04:00") for the wall time in the target IANA zone.
function offsetStr(y, mo, d, h, mi, tz) {
  const wallAsUTC = Date.UTC(y, mo - 1, d, h, mi, 0);
  const dtf = new Intl.DateTimeFormat('en-US', { timeZone: tz, hour12: false, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
  const p = dtf.formatToParts(new Date(wallAsUTC)).reduce((a, x) => { a[x.type] = x.value; return a; }, {});
  let hh = parseInt(p.hour, 10); if (hh === 24) hh = 0;
  const tzAsUTC = Date.UTC(parseInt(p.year, 10), parseInt(p.month, 10) - 1, parseInt(p.day, 10), hh, parseInt(p.minute, 10), parseInt(p.second, 10));
  const offMin = Math.round((tzAsUTC - wallAsUTC) / 60000);
  const sign = offMin >= 0 ? '+' : '-';
  const a = Math.abs(offMin);
  return sign + pad(Math.floor(a / 60)) + ':' + pad(a % 60);
}

const off = offsetStr(Y, Mo, D, hour, minute, timeZone);
const endTotal = hour * 60 + minute + durationMinutes;
const endH = Math.floor(endTotal / 60);
const endM = endTotal % 60;

const startDateTime = `${dateStr}T${pad(hour)}:${pad(minute)}:00${off}`;
const endDateTime = `${dateStr}T${pad(endH)}:${pad(endM)}:00${off}`;

const eventSummary = `${service} - ${customerName}`;
const eventDescription = `Automated Phone Booking - ${businessName}\n` +
  `- Customer Name: ${customerName}\n` +
  `- Contact Phone: ${customerPhone}\n` +
  `- Requested Service: ${service}\n` +
  `- Special Notes: ${notes || 'None'}\n` +
  `- Booked Via: Autonomous Inbound Call Admin Agent`;

return {
  json: {
    customerName, customerPhone, dateStr, timeStr, service, notes, durationMinutes,
    timeZone, startDateTime, endDateTime, eventSummary, eventDescription,
    location: businessName
  }
};

const bookingData = $('Parse Booking Details').first().json;
const gcalResult = $input.item.json;

// Check if creation succeeded or had error
const hasError = !!(gcalResult.error || gcalResult.errorMessage);
const bookingId = gcalResult.id || `evt_local_${Date.now()}`;

if (hasError) {
  return {
    json: {
      success: false,
      booking_id: null,
      customer_name: bookingData.customerName,
      date: bookingData.dateStr,
      time: bookingData.timeStr,
      spoken_summary: `I apologize, but I encountered an issue while finalizing the calendar reservation for ${bookingData.timeStr}. Could I please take your phone number for our team to call you right back to confirm?`
    }
  };
}

const spoken = `All confirmed, ${bookingData.customerName}! I have scheduled your appointment for ${bookingData.service} on ${bookingData.dateStr} at ${bookingData.timeStr}. We look forward to seeing you!`;

return {
  json: {
    success: true,
    booking_id: bookingId,
    customer_name: bookingData.customerName,
    customer_phone: bookingData.customerPhone,
    date: bookingData.dateStr,
    time: bookingData.timeStr,
    service: bookingData.service,
    spoken_summary: spoken
  }
};
